INSERT INTO `messages` VALUES (1173,'susha','aminsec','1737354420083','hey man whats up'),(1174,'aminsec','susha','1737354429495','hey susha thanks how are you doing'),(1175,'susha','aminsec','1737354439851','thanks man im good'),(1176,'aminsec','susha','1737354491384','wanna hit the gym?'),(1177,'susha','aminsec','1737354501650','yeah man thats why i texted you'),(1178,'aminsec','susha','1737354525899','im gonna get ready'),(1179,'susha','aminsec','1737354534595','alright'),(1180,'susha','aminsec','1737354543981','i will see you around 8 pm'),(1181,'aminsec','susha','1737354549687','8 pm?'),(1182,'susha','aminsec','1737354553633','yeah '),(1183,'aminsec','susha','1737354558281','it\'s too late'),(1184,'susha','aminsec','1737354565448','6 pm?'),(1185,'aminsec','susha','1737354568366','cool'),(1186,'susha','aminsec','1737354571882','find see ya'),(1187,'aminsec','susha','1737354574633','see ya'),(1188,'aminsec','Coder','1737553858954','Hey coder, \nhow things goin\'?'),(1189,'Coder','aminsec','1737553886496','hey aminsec, how are you?\nim great'),(1190,'aminsec','Coder','1737553929148','I just read your new blog, that was amazing'),(1191,'Coder','aminsec','1737553946125','Oh, very kind body'),(1192,'Coder','aminsec','1737553953310','im happy that you liked it '),(1193,'aminsec','Coder','1737553977963','How did get the idea?'),(1194,'Coder','aminsec','1737554007294','i was just thinking and it pop up in my mind  :))'),(1195,'aminsec','Coder','1737554019957','I wish i had your mind'),(1196,'Coder','aminsec','1737554035226','😄😄'),(1197,'Coder','aminsec','1737554040656','you already have it bro '),(1198,'aminsec','Coder','1737554052891','IDK, maybe '),(1199,'aminsec','Coder','1737554063007','im gonna try to post something new'),(1200,'Coder','aminsec','1737554084458','im waiting for it body ✌️'),(1201,'aminsec','Coder','1737554102756','thanks man, i will keep you in touch when i post it '),(1202,'Coder','aminsec','1737554106599','sure , thanks '),(1203,'aminsec','Coder','1737554113617','okay man, see ya '),(1204,'Coder','aminsec','1737554123316','good luck,\nsee ya'),(1205,'Coder','aminsec','1737554237554','hey body, do you some free times?'),(1206,'aminsec','Coder','1737554340527','hey man ofcourse, what\'s the deal?'),(1207,'Coder','aminsec','1737554366004','i just wrote new blog, but i didn\'t published it yet'),(1208,'aminsec','Coder','1737554394021','such a nice, a new bomb is coming :))'),(1209,'Coder','aminsec','1737554402686','thanks body 😂'),(1210,'Coder','aminsec','1737554419473','can you check it with magic link?'),(1211,'aminsec','Coder','1737554427523','yes man send the link'),(1212,'Coder','aminsec','1737554452353','Sure here you are:\nhttp://sancity.blog:8081/blogs/magicLink?token=3cb72dd1060517e3c3b543f9e5cc86b5'),(1214,'aminsec','Coder','1737554560771','Wow man, \nthis is a good blog'),(1215,'aminsec','Coder','1737554577102','but why is short?'),(1216,'Coder','aminsec','1737554631540','Actually, i tried to write some more, but i have to publish it till here'),(1217,'Coder','aminsec','1737554643434','Maybe i updated soon'),(1218,'aminsec','Coder','1737554653337','I see'),(1219,'aminsec','Coder','1737554662318','That\'s great BTW'),(1220,'aminsec','Coder','1737554669517','go ahead and publish it'),(1221,'aminsec','Coder','1737554686233','im sure it\'s gonna take more than 500 likes'),(1222,'Coder','aminsec','1737554695484','I hope so'),(1223,'Coder','aminsec','1737554705171','thanks body for your help'),(1224,'aminsec','Coder','1737554719158','i did nothing, good luck man'),(1225,'Coder','aminsec','1737554723136','thanks man'),(1226,'Coder','aminsec','1737554750950','bye'),(1227,'aminsec','Coder','1737554755469','bye'),(1228,'writer_fly','aminsec','1737554840969','Hello aminsec'),(1229,'writer_fly','aminsec','1737554862620','I saw a notification that you liked my blog'),(1230,'writer_fly','aminsec','1737554895728','thanks for supporting me and this is honor'),(1231,'writer_fly','aminsec','1737554907632','Do you have any suggestion to make the blog better?'),(1232,'aminsec','writer_fly','1737555069078','Hello friend'),(1233,'aminsec','writer_fly','1737555079028','Thanks for saying'),(1234,'aminsec','writer_fly','1737555096362','Yeah you\'re blog was good \ni liked it'),(1235,'aminsec','writer_fly','1737555144936','No man, it didn\'t have any cons '),(1236,'aminsec','writer_fly','1737555150610','Keep goin\''),(1237,'writer_fly','aminsec','1737555181535','Thanks a lot sir '),(1238,'writer_fly','aminsec','1737555271915','I appreciate it'),(1239,'aminsec','writer_fly','1737562540818','good luck man'),(1240,'writer_fly','aminsec','1737562604633','❤️');
